/// `init` options the guest never gets. The write-back cache would let the
/// guest kernel merge and delay writes, so they would reach the host, and
/// the audit, late and attributed to whichever thread flushes them. The DAX
/// bits are refused so the guest does not negotiate per-file DAX, but that
/// alone does not prevent DAX: a guest maps host files only through a
/// shared-memory window the virtio-fs device exposes, and the device must
/// not expose one (the Task 12 device does not). Through such a window
/// reads and writes would bypass FUSE, and this audit, entirely.
const MASKED_OPTIONS: FsOptions = FsOptions::WRITEBACK_CACHE
    .union(FsOptions::MAP_ALIGNMENT)
    .union(FsOptions::PERFILE_DAX);

/// How much is recorded.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum AuditLevel {
    /// Opens, closes, mutations and denials.
    #[default]
    Normal,
    /// Also every read, write and directory listing, and lookups of missing
    /// names.
    Verbose,
}

/// How an [`AuditFs`] records.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct AuditFsOptions {
    pub level: AuditLevel,
    /// Files larger than this are closed without a hash (`skipped_size`).
    pub hash_max_bytes: u64,
    /// Present and take the ownership override (`--ownership override`).
    pub ownership: bool,
    /// With `ownership`, the owner shown for what carries no override: the
    /// session's own identity.
    pub owner: (u32, u32),
}

impl Default for AuditFsOptions {
    /// Normal level, 64 MiB hashing limit.
    fn default() -> Self {
        AuditFsOptions {
            level: AuditLevel::Normal,
            hash_max_bytes: 64 * 1024 * 1024,
            ownership: false,
            owner: invoking_user(),
        }
    }
}

/// The audited filesystem over `F`, for one share.
pub struct AuditFs<F: FileSystem<Inode = u64, Handle = u64>> {
    inner: F,
    guest_path: String,
    host_root: String,
    cache_policy: &'static str,
    level: AuditLevel,
    paths: RwLock<PathMap>,
    handles: HandleTable,
    events: Arc<Events>,
    hasher: HashWorker,
    generations: Arc<Generations>,
    /// The path rules in force, read once per request.
    rules: LiveRules,
    /// What the boot scan found denied, by host identity.
    denied_ids: Arc<DeniedIds>,
    /// Whether the ownership override is presented and taken
    /// (`--ownership override`): the owner, the special bits and the
    /// device kind the guest is to see, kept in an xattr of boxcar's own
    /// on the host file (`crate::ownership`).
    ownership: bool,
    /// The owner shown for what carries no override, with `ownership`.
    owner: (u32, u32),
    /// The override each inode carries, read once and kept until the inode
    /// is forgotten or the override changed; `None` for an inode without.
    overrides: Mutex<HashMap<u64, Option<Override>>>,
}

/// A request the path rules refuse: its errno, and the glob that refused it
/// (none for a change outside `writable`, or a path not known whole).
#[derive(Clone, Debug, PartialEq, Eq)]
struct Refusal {
    errno: i32,
    rule: Option<String>,
}

impl Refusal {
    /// EACCES, by `glob`: a denied path, a program not to be run.
    fn by(glob: &str) -> Refusal {
        Refusal {
            errno: libc::EACCES,
            rule: Some(glob.to_owned()),
        }
    }

    /// EROFS: a change outside `writable`.
    fn read_only() -> Refusal {
        Refusal {
            errno: libc::EROFS,
            rule: None,
        }
    }

    /// A node whose path is not known whole, under rules that would have
    /// to read it: refused, EROFS for a change and EACCES otherwise.
    fn unknown(change: bool) -> Refusal {
        Refusal {
            errno: if change { libc::EROFS } else { libc::EACCES },
            rule: None,
        }
    }
}

/// Whether `name` is `.` or `..`, which a lookup may name.
fn is_dot(name: &[u8]) -> bool {
    name == b"." || name == b".."
}

/// What an existing entry is checked for, besides being denied.
#[derive(Clone, Copy)]
struct Existing {
    /// A directory holding denied entries (a rename, an rmdir).
    holding: bool,
    /// A refused program (a rename, a create that would open it).
    programs: bool,
}

/// The open flags that read a directory: what `opendir` passes on.
const OPENDIR_FLAGS: u32 =
    (libc::O_NONBLOCK | libc::O_CLOEXEC | libc::O_NOATIME | libc::O_LARGEFILE) as u32;

impl<F: FileSystem<Inode = u64, Handle = u64>> AuditFs<F> {
    /// Wraps `inner`, which serves `share`. `host_root_fd` is an open
    /// descriptor of the share's host directory, which closed files are
    /// reopened beneath to hash them. Events go to `sink`.
    pub fn new(
        inner: F,
        share: &FsShareConfig,
        host_root_fd: OwnedFd,
        sink: AuditSink,
        opts: AuditFsOptions,
    ) -> Self {
        Self::with_hash(inner, share, host_root_fd, sink, opts, hash_file)
    }

    /// Looks for a closed file beneath `lower` too, when the share's own
    /// directory has none: an image session's lower layer.
    pub fn with_lower_root(self, lower: OwnedFd) -> Self {
        self.hasher.add_root(lower);
        self
    }

    /// [`new`](Self::new), hashing closed files with `hash`.
    pub(crate) fn with_hash(
        inner: F,
        share: &FsShareConfig,
        host_root_fd: OwnedFd,
        sink: AuditSink,
        opts: AuditFsOptions,
        hash: HashFn,
    ) -> Self {
        let events = Arc::new(Events::new(sink, share.tag.clone()));
        let hasher = HashWorker::with_hash(
            &share.tag,
            host_root_fd,
            opts.hash_max_bytes,
            Arc::clone(&events),
            hash,
        );
        AuditFs {
            inner,
            guest_path: share.guest_path.clone(),
            host_root: share.host_dir.to_string_lossy().into_owned(),
            cache_policy: share.cache.as_str(),
            level: opts.level,
            paths: RwLock::new(PathMap::new()),
            handles: HandleTable::new(),
            events,
            hasher,
            generations: Arc::default(),
            rules: Arc::new(ArcSwap::from_pointee(PathRules::allow_all())),
            denied_ids: Arc::default(),
            ownership: opts.ownership,
            owner: opts.owner,
            overrides: Mutex::new(HashMap::new()),
        }
    }

    /// Puts `rules` in force on this share, with `denied`, the host
    /// identities the boot scan found denied in it ([`crate::scan`]).
    pub fn with_rules(mut self, rules: LiveRules, denied: Arc<DeniedIds>) -> Self {
        self.rules = rules;
        self.denied_ids = denied;
        self
    }

    /// Returns once every close queued for hashing has been recorded.
    pub fn flush_hashes(&self) {
        self.hasher.flush();
    }

    /// Starts the hash threads again after [`shutdown`](Self::shutdown)
    /// (a device reset), so that closes are hashed off the FUSE reply path
    /// once more; nothing changes while they run. The device calls it at
    /// every activation.
    pub fn restart_hashing(&self) {
        self.hasher.restart();
    }

    /// How many hash threads are running: 0 after a shutdown, when closes
    /// are hashed on the thread that releases them.
    pub fn hash_threads(&self) -> usize {
        self.hasher.threads_alive()
    }

    /// Closes every handle the guest left open (see `destroy`), records
    /// the closes still being hashed, and stops the hash threads. Dropping
    /// the filesystem does the same. Call it before closing the audit log.
    pub fn shutdown(&self) {
        self.close_open_handles();
        self.hasher.shutdown();
    }

    /// Every inode the path map knows, the root included, ascending.
    pub fn known_inodes(&self) -> Vec<u64> {
        self.read_paths().inodes()
    }

    /// The wrapped filesystem.
    pub fn inner(&self) -> &F {
        &self.inner
    }

    fn read_paths(&self) -> RwLockReadGuard<'_, PathMap> {
        // Every update leaves the map consistent.
        self.paths.read().unwrap_or_else(PoisonError::into_inner)
    }

    fn write_paths(&self) -> RwLockWriteGuard<'_, PathMap> {
        self.paths.write().unwrap_or_else(PoisonError::into_inner)
    }

    fn verbose(&self) -> bool {
        self.level == AuditLevel::Verbose
    }

    /// EIO once the audit log has failed: the change would go unrecorded,
    /// so it is not made (see the module docs).
    fn refuse_if_log_failed(&self) -> io::Result<()> {
        if self.events.log_failed() {
            Err(io::Error::from_raw_os_error(libc::EIO))
        } else {
            Ok(())
        }
    }

    /// The content of `ino` may have changed: a close of it still waiting
    /// for its hash is `raced`.
    fn content_changed(&self, ino: u64) {
        let host = self.read_paths().host_id(ino);
        self.generations.changed(FileKey::of(ino, host));
    }

    /// The path of `ino`, for a record: its text and, for a name that is
    /// not UTF-8, its bytes.
    fn path(&self, ino: u64) -> PathText {
        self.read_paths().path_text(ino)
    }

    /// The path of `name` in `parent`, for a record.
    fn child(&self, parent: u64, name: &CStr) -> PathText {
        self.read_paths().child_text(parent, name.to_bytes())
    }

    /// A reply handed the kernel `entry` as `name` in `parent`.
    fn remember(&self, parent: u64, name: &[u8], entry: &Entry) {
        let mut paths = self.write_paths();
        paths.insert(parent, name, entry.inode);
        paths.set_host_id(entry.inode, host_id(&entry.attr));
    }

    /// Whom a read or write through `handle` is attributed to: the opener
    /// (`Attrib::Handle`) when the request has no usable caller of its own,
    /// else the caller.
    fn io_subject(
        &self,
        ctx: &Context,
        opener: Option<Subject>,
        by_kernel: bool,
    ) -> (Subject, Attrib) {
        match opener {
            Some(opener) if by_kernel || ctx.pid == 0 => (opener, Attrib::Handle),
            _ => (subject(ctx), Attrib::Caller),
        }
    }

    fn denied(&self, ctx: &Context, op: &str, path: PathText, errno: i32) {
        let payload = Payload::FsDenied(FsDenied {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            op: op.to_owned(),
            errno,
            reason: None,
            rule: None,
        });
        self.events.record(Some(subject(ctx)), payload);
    }

    /// Records `refusal` of `op` on `path` and returns its error. The
    /// request never reached the wrapped filesystem.
    fn refuse(&self, ctx: &Context, op: &str, path: PathText, refusal: Refusal) -> io::Error {
        let payload = Payload::FsDenied(FsDenied {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            op: op.to_owned(),
            errno: refusal.errno,
            reason: Some("policy".to_owned()),
            rule: refusal.rule,
        });
        self.events.record(Some(subject(ctx)), payload);
        io::Error::from_raw_os_error(refusal.errno)
    }

    /// The guest path of a share-relative path.
    fn guest(&self, relative: &[u8]) -> Vec<u8> {
        guest_path(&self.guest_path, relative)
    }

    /// A request naming `name` in `parent`: refused when the path is
    /// denied, or, for a `change`, not writable.
    fn check_name(
        &self,
        rules: &PathRules,
        parent: u64,
        name: &[u8],
        change: bool,
    ) -> Result<(), Refusal> {
        if !rules.enforcing() {
            return Ok(());
        }
        let Some(relative) = self.read_paths().rooted_child(parent, name) else {
            return Err(Refusal::unknown(change));
        };
        let path = self.guest(&relative);
        if let Some(glob) = rules.denied(&path) {
            return Err(Refusal::by(glob));
        }
        if change && !rules.writable(&path) {
            return Err(Refusal::read_only());
        }
        Ok(())
    }

    /// A request on `ino`: refused when any name the map knows for it, or
    /// its identity, is denied; for `programs`, when one of its names or
    /// its identity is a refused program no exec exception lifts; for a
    /// `change`, when any name is not writable.
    fn check_inode(
        &self,
        rules: &PathRules,
        ino: u64,
        change: bool,
        programs: bool,
    ) -> Result<(), Refusal> {
        if !rules.enforcing() {
            return Ok(());
        }
        let (known, id) = {
            let paths = self.read_paths();
            (paths.known_paths(ino), paths.host_id(ino))
        };
        let Some(known) = known else {
            return Err(Refusal::unknown(change));
        };
        let paths: Vec<Vec<u8>> = known.iter().map(|relative| self.guest(relative)).collect();
        for path in &paths {
            if let Some(glob) = rules.denied(path) {
                return Err(Refusal::by(glob));
            }
        }
        if let Some(glob) = id.and_then(|id| self.denied_ids.denied(id)) {
            return Err(Refusal::by(glob));
        }
        if programs {
            for path in &paths {
                if let Some(glob) = rules.exec_denied(path) {
                    return Err(Refusal::by(glob));
                }
            }
            if let Some(glob) = id.and_then(|id| self.denied_ids.exec(id)) {
                if !paths.iter().any(|path| rules.exec_lifted(path)) {
                    return Err(Refusal::by(glob));
                }
            }
        }
        if change && !paths.iter().all(|path| rules.writable(path)) {
            return Err(Refusal::read_only());
        }
        Ok(())
    }

    /// A reply about to hand the kernel `entry`: refused when its host
    /// identity is denied, or, for `.` and `..`, when its path is.
    fn check_reply(&self, rules: &PathRules, entry: &Entry, dot: bool) -> Result<(), Refusal> {
        if entry.inode == 0 {
            return Ok(());
        }
        if let Some(glob) = self.denied_ids.denied(host_id(&entry.attr)) {
            return Err(Refusal::by(glob));
        }
        if dot && rules.enforcing() {
            if let Some(relative) = self.read_paths().rooted_path(entry.inode) {
                if let Some(glob) = rules.denied(&self.guest(&relative)) {
                    return Err(Refusal::by(glob));
                }
            }
        }
        Ok(())
    }

    /// What `name` in `parent` is now, read beneath the share's root with
    /// no symlink followed: refused when it is denied by its identity, or
    /// as `what` asks, a directory holding denied entries or a refused
    /// program no exec exception lifts by this name. Nothing to read when
    /// the scan found nothing.
    fn check_existing(
        &self,
        rules: &PathRules,
        parent: u64,
        name: &[u8],
        what: Existing,
    ) -> Result<(), Refusal> {
        if self.denied_ids.is_empty() {
            return Ok(());
        }
        let Some(relative) = self.read_paths().rooted_child(parent, name) else {
            return Err(Refusal::unknown(true));
        };
        let host = Path::new(&self.host_root).join(OsStr::from_bytes(&relative[1..]));
        let Ok(meta) = std::fs::symlink_metadata(host) else {
            // Nothing there yet.
            return Ok(());
        };
        let id = FileId {
            dev: meta.dev(),
            ino: meta.ino(),
        };
        if let Some(glob) = self.denied_ids.denied(id) {
            return Err(Refusal::by(glob));
        }
        if what.holding {
            if let Some(glob) = self.denied_ids.holds(id) {
                return Err(Refusal::by(glob));
            }
        }
        if what.programs && !rules.exec_lifted(&self.guest(&relative)) {
            if let Some(glob) = self.denied_ids.exec(id) {
                return Err(Refusal::by(glob));
            }
        }
        Ok(())
    }

    /// A rename's name `name` in `parent`, beyond the checks of any change:
    /// refused when it is a denied glob's literal prefix or an ancestor of
    /// one, or a refused program by its name.
    fn check_moved(&self, rules: &PathRules, parent: u64, name: &[u8]) -> Result<(), Refusal> {
        if !rules.enforcing() {
            return Ok(());
        }
        let Some(relative) = self.read_paths().rooted_child(parent, name) else {
            return Err(Refusal::unknown(true));
        };
        let path = self.guest(&relative);
        if let Some(glob) = rules.holds_prefix(&path) {
            return Err(Refusal::by(glob));
        }
        if let Some(glob) = rules.exec_denied(&path) {
            return Err(Refusal::by(glob));
        }
        Ok(())
    }

    /// Whether anything is checked: rules in force, or what the scan found.
    fn policing(&self) -> bool {
        self.rules.load().enforcing() || !self.denied_ids.is_empty()
    }

    /// The node-id gate: while rules are in force, a request on an id the
    /// map does not hold, or on one whose identity is denied, is refused.
    fn gate(&self, ctx: &Context, op: &str, ino: u64) -> io::Result<()> {
        if !self.policing() {
            return Ok(());
        }
        let held = {
            let paths = self.read_paths();
            paths.contains(ino).then(|| paths.host_id(ino))
        };
        let refusal = match held {
            None => Refusal::unknown(false),
            Some(id) => match id.and_then(|id| self.denied_ids.denied(id)) {
                Some(glob) => Refusal::by(glob),
                None => return Ok(()),
            },
        };
        Err(self.refuse(ctx, op, self.path(ino), refusal))
    }

    /// Tracks a handle an open or create returned. Without one (a
    /// filesystem with zero-message opens) there is nothing to close.
    fn opened(&self, fh: u64, entry: HandleEntry) {
        if fh != 0 {
            self.handles.insert(fh, entry);
        }
    }

    /// Records the close of a handle the guest released, now or once it is
    /// hashed.
    fn close(&self, ctx: &Context, fh: u64, entry: HandleEntry) {
        let (subject, attrib) = if ctx.pid == 0 {
            (entry.opener, Attrib::Handle)
        } else {
            (subject(ctx), Attrib::Caller)
        };
        self.record_close(fh, entry, subject, attrib);
    }

    /// Closes every handle still open, as the guest's filesystem goes away
    /// (unmount, a driver unbind, a guest panic, the VM stopping) without
    /// releasing them, and waits for their hashes. At the normal level the
    /// close is the only record of what was written through a handle, so
    /// none may be dropped. There is no request, so each close is
    /// attributed to the handle's opener.
    fn close_open_handles(&self) {
        for (fh, entry) in self.handles.drain() {
            let opener = entry.opener;
            self.record_close(fh, entry, opener, Attrib::Handle);
        }
        self.hasher.flush();
    }

    /// Records `entry`'s close as `subject`: at once when nothing needs
    /// hashing, else once the hash worker has hashed the file.
    fn record_close(&self, fh: u64, entry: HandleEntry, subject: Subject, attrib: Attrib) {
        if self.events.log_failed() {
            // Nothing is recorded any more; the file need not be read.
            return;
        }
        // The producer's time: the release is now, whenever the hash that
        // completes the record is made.
        let ts_release_ns = realtime_ns();
        let (path, rel_path, deleted, expected) = {
            let paths = self.read_paths();
            (
                paths.path_text(entry.ino),
                paths.relative_path(entry.ino),
                paths.is_deleted(entry.ino),
                paths.host_id(entry.ino),
            )
        };
        let changed = entry.changed();
        let close = FsClose {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            path_at_open: entry.path_at_open,
            fh,
            bytes_read: entry.bytes_read,
            bytes_written: entry.bytes_written,
            size: None,
            blake3: None,
            hash_status: HashStatus::NotHashed,
            open_seq: entry.open_seq,
            attrib,
            ts_release_ns,
        };
        let status = if !changed {
            HashStatus::NotHashed
        } else if deleted {
            HashStatus::Gone
        } else {
            match rel_path.map(CString::new) {
                Some(Ok(rel_path)) => {
                    // Watched from the close, before any later change can
                    // reach the file.
                    let watch = self.generations.watch(FileKey::of(entry.ino, expected));
                    self.hasher.submit(HashJob {
                        rel_path,
                        expected,
                        subject,
                        close,
                        watch: Some(watch),
                    });
                    return;
                }
                // The path is not fully known, so the file cannot be found.
                _ => HashStatus::Error,
            }
        };
        let close = FsClose {
            hash_status: status,
            ..close
        };
        self.events.record(Some(subject), Payload::FsClose(close));
    }
}

/// The host identity in a reply's attributes.
/// A `readdirplus` entry with node id 0: a name, and nothing of the file,
/// its attributes included.
fn bare_entry() -> Entry {
    Entry {
        inode: 0,
        generation: 0,
        // SAFETY: stat64 is plain data; all-zero is a valid value.
        attr: unsafe { std::mem::zeroed() },
        attr_flags: 0,
        attr_timeout: Duration::ZERO,
        entry_timeout: Duration::ZERO,
    }
}

fn host_id(attr: &stat64) -> FileId {
    FileId {
        dev: attr.st_dev,
        ino: attr.st_ino,
    }
}

/// Whether an open's access mode lets the handle write: anything but
/// `O_RDONLY` (mode 3, "no access", counts as writing).
fn opens_for_writing(flags: u32) -> bool {
    flags as libc::c_int & libc::O_ACCMODE != libc::O_RDONLY
}

/// The mode a node is created with.
fn effective_mode(mode: u32, umask: u32) -> u32 {
    mode & !(umask & 0o777)
}

/// Seconds since the epoch of a `setattr` time: the time asked for, or, for
/// "now", the time the reply reports (or the clock, if it failed).
fn set_time(asked: i64, now: bool, reply: Option<i64>) -> i64 {
    if !now {
        return asked;
    }
    reply.unwrap_or_else(|| {
        let since = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or(Duration::ZERO);
        i64::try_from(since.as_secs()).unwrap_or(i64::MAX)
    })
}

/// The fields a `setattr` asked to change.
fn set_attrs(attr: &stat64, valid: SetattrValid, reply: Option<&stat64>) -> SetAttr {
    let has = |bit: SetattrValid| valid.contains(bit);
    SetAttr {
        mode: has(SetattrValid::MODE).then_some(attr.st_mode & 0o7777),
        uid: has(SetattrValid::UID).then_some(attr.st_uid),
        gid: has(SetattrValid::GID).then_some(attr.st_gid),
        size: has(SetattrValid::SIZE).then(|| u64::try_from(attr.st_size).unwrap_or(0)),
        atime: has(SetattrValid::ATIME).then(|| {
            set_time(
                attr.st_atime,
                has(SetattrValid::ATIME_NOW),
                reply.map(|r| r.st_atime),
            )
        }),
        mtime: has(SetattrValid::MTIME).then(|| {
            set_time(
                attr.st_mtime,
                has(SetattrValid::MTIME_NOW),
                reply.map(|r| r.st_mtime),
            )
        }),
    }
}

impl<F: FileSystem<Inode = u64, Handle = u64>> Drop for AuditFs<F> {
    fn drop(&mut self) {
        self.shutdown();
    }
}

impl<F: FileSystem<Inode = u64, Handle = u64>> FileSystem for AuditFs<F> {
    type Inode = u64;
    type Handle = u64;

    forward! {
        init: audited,
        destroy: audited,
        lookup: audited,
        forget: audited,
        batch_forget: audited,
        getattr: audited,
        setattr: audited,
        readlink: audited,
        symlink: audited,
        mknod: audited,
        mkdir: audited,
        unlink: audited,
        rmdir: audited,
        rename: audited,
        link: audited,
        open: audited,
        create: audited,
        read: audited,
        write: audited,
        flush: forward,
        fsync: forward,
        fallocate: audited,
        release: audited,
        statfs: audited,
        setxattr: audited,
        getxattr: audited,
        listxattr: audited,
        removexattr: audited,
        opendir: audited,
        readdir: audited,
        readdirplus: audited,
        fsyncdir: forward,
        releasedir: forward,
        setupmapping: forward,
        removemapping: forward,
        access: audited,
        lseek: forward,
        getlk: forward,
        setlk: forward,
        setlkw: forward,
        ioctl: forward,
        bmap: forward,
        poll: forward,
        notify_reply: forward,
        id_remap: forward,
    }

    fn init(&self, capable: FsOptions) -> io::Result<FsOptions> {
        let wanted = self.inner.init(capable - MASKED_OPTIONS)? - MASKED_OPTIONS;
        let mount = Payload::FsMount(FsMount {
            mount: self.events.mount(),
            guest_path: self.guest_path.clone(),
            host_root: self.host_root.clone(),
            cache_policy: self.cache_policy.to_owned(),
        });
        self.events.record(None, mount);
        Ok(wanted)
    }

    fn destroy(&self) {
        // The guest's filesystem is going away: its open handles are closed
        // (and hashed) while the paths and the files are still there.
        self.close_open_handles();
        self.inner.destroy();
        // The guest holds no inodes any more.
        self.write_paths().reset();
    }

    fn lookup(&self, ctx: &Context, parent: u64, name: &CStr) -> io::Result<Entry> {
        let rules = self.rules.load();
        let dot = is_dot(name.to_bytes());
        if !dot {
            if let Err(refusal) = self.check_name(&rules, parent, name.to_bytes(), false) {
                return Err(self.refuse(ctx, "lookup", self.child(parent, name), refusal));
            }
        }
        let result = self.inner.lookup(&squash(ctx), parent, name);
        if let Ok(entry) = &result {
            if let Err(refusal) = self.check_reply(&rules, entry, dot) {
                // The kernel never gets the inode: its lookup goes back.
                self.inner.forget(&squash(ctx), entry.inode, 1);
                return Err(self.refuse(ctx, "lookup", self.child(parent, name), refusal));
            }
        }
        match &result {
            Ok(entry) => self.remember(parent, name.to_bytes(), entry),
            Err(e) => {
                let errno = errno(e);
                let refused = errno == libc::EACCES || errno == libc::EPERM;
                if refused || (self.verbose() && errno == libc::ENOENT) {
                    self.denied(ctx, "lookup", self.child(parent, name), errno);
                }
            }
        }
        self.present_entry(ctx, result)
    }

    fn getattr(
        &self,
        ctx: &Context,
        inode: u64,
        handle: Option<u64>,
    ) -> io::Result<(stat64, Duration)> {
        self.gate(ctx, "getattr", inode)?;
        let (mut st, ttl) = self.inner.getattr(&squash(ctx), inode, handle)?;
        self.present(ctx, inode, &mut st);
        Ok((st, ttl))
    }

    fn readlink(&self, ctx: &Context, inode: u64) -> io::Result<Vec<u8>> {
        self.gate(ctx, "readlink", inode)?;
        self.inner.readlink(&squash(ctx), inode)
    }

    fn statfs(&self, ctx: &Context, inode: u64) -> io::Result<statvfs64> {
        self.gate(ctx, "statfs", inode)?;
        self.inner.statfs(&squash(ctx), inode)
    }

    fn getxattr(
        &self,
        ctx: &Context,
        inode: u64,
        name: &CStr,
        size: u32,
    ) -> io::Result<GetxattrReply> {
        self.gate(ctx, "getxattr", inode)?;
        if is_ownership_xattr(name) {
            // Boxcar's own: the guest sees it as the attributes, never as
            // an xattr.
            return Err(io::Error::from_raw_os_error(libc::ENODATA));
        }
        self.inner.getxattr(&squash(ctx), inode, name, size)
    }

    fn listxattr(&self, ctx: &Context, inode: u64, size: u32) -> io::Result<ListxattrReply> {
        self.gate(ctx, "listxattr", inode)?;
        // A count (size 0) asks for the names instead, so that the count
        // is right without boxcar's own: the kernel lists at most
        // XATTR_LIST_MAX bytes, so that many never fall short.
        let asked = if size == 0 { XATTR_LIST_MAX } else { size };
        match self.inner.listxattr(&squash(ctx), inode, asked)? {
            ListxattrReply::Names(names) => {
                let names = without_ownership(&names);
                if size == 0 {
                    Ok(ListxattrReply::Count(names.len() as u32))
                } else {
                    Ok(ListxattrReply::Names(names))
                }
            }
            count => Ok(count),
        }
    }

    fn opendir(
        &self,
        ctx: &Context,
        inode: u64,
        flags: u32,
    ) -> io::Result<(Option<u64>, OpenOptions)> {
        self.gate(ctx, "opendir", inode)?;
        // Only what reads a directory: never O_TMPFILE or a write mode,
        // which would make an unnamed host file no record names.
        self.inner
            .opendir(&squash(ctx), inode, flags & OPENDIR_FLAGS)
    }

    fn forget(&self, ctx: &Context, inode: u64, count: u64) {
        self.inner.forget(&squash(ctx), inode, count);
        self.write_paths().forget(inode, count);
        self.overrides().remove(&inode);
    }

    fn batch_forget(&self, ctx: &Context, requests: Vec<(u64, u64)>) {
        {
            let mut paths = self.write_paths();
            let mut overrides = self.overrides();
            for &(inode, count) in &requests {
                paths.forget(inode, count);
                overrides.remove(&inode);
            }
        }
        self.inner.batch_forget(&squash(ctx), requests);
    }

    fn setattr(
        &self,
        ctx: &Context,
        inode: u64,
        attr: stat64,
        handle: Option<u64>,
        valid: SetattrValid,
    ) -> io::Result<(stat64, Duration)> {
        self.refuse_if_log_failed()?;
        let path = self.path(inode);
        if let Err(refusal) = self.check_inode(&self.rules.load(), inode, true, false) {
            return Err(self.refuse(ctx, "setattr", path, refusal));
        }
        let mut valid = valid;
        let owner_taken = self.ownership && valid.intersects(SetattrValid::UID | SetattrValid::GID);
        if owner_taken {
            // The owner the guest sets goes into the override; the host
            // file stays the invoking user's.
            let mut over = self.override_of(ctx, inode).unwrap_or_default();
            if valid.contains(SetattrValid::UID) {
                over.uid = Some(attr.st_uid);
            }
            if valid.contains(SetattrValid::GID) {
                over.gid = Some(attr.st_gid);
            }
            if let Err(error) = self.write_override(ctx, inode, &over) {
                let payload = Payload::FsSetattr(FsSetattr {
                    mount: self.events.mount(),
                    path: path.path,
                    path_b64: path.path_b64,
                    set: set_attrs(&attr, valid, None),
                    result: op_result::<()>(&Err(io::Error::from_raw_os_error(errno(&error)))),
                });
                self.events.record(Some(subject(ctx)), payload);
                return Err(error);
            }
            valid.remove(SetattrValid::UID | SetattrValid::GID);
        }
        let result = if owner_taken && valid.is_empty() {
            // Nothing left for the host: the attributes as they now are.
            self.inner.getattr(&squash(ctx), inode, handle)
        } else {
            self.inner.setattr(&squash(ctx), inode, attr, handle, valid)
        };
        let result = result.map(|(mut st, ttl)| {
            self.present(ctx, inode, &mut st);
            (st, ttl)
        });
        if result.is_ok() && valid.contains(SetattrValid::SIZE) {
            self.content_changed(inode);
            if let Some(fh) = handle {
                self.handles.update(fh, |e| e.truncated = true);
            }
        }
        let reply = result.as_ref().ok().map(|(st, _)| st);
        let payload = Payload::FsSetattr(FsSetattr {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            set: set_attrs(&attr, valid, reply),
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn symlink(
        &self,
        ctx: &Context,
        linkname: &CStr,
        parent: u64,
        name: &CStr,
    ) -> io::Result<Entry> {
        self.refuse_if_log_failed()?;
        let path = self.child(parent, name);
        if let Err(refusal) = self.check_name(&self.rules.load(), parent, name.to_bytes(), true) {
            return Err(self.refuse(ctx, "symlink", path, refusal));
        }
        let result = self.inner.symlink(&squash(ctx), linkname, parent, name);
        if let Ok(entry) = &result {
            self.remember(parent, name.to_bytes(), entry);
        }
        let result = self.present_entry(ctx, result);
        let payload = Payload::FsSymlink(FsSymlink {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            target: c_text(linkname),
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn mknod(
        &self,
        ctx: &Context,
        inode: u64,
        name: &CStr,
        mode: u32,
        rdev: u32,
        umask: u32,
    ) -> io::Result<Entry> {
        self.refuse_if_log_failed()?;
        let path = self.child(inode, name);
        if let Err(refusal) = self.check_name(&self.rules.load(), inode, name.to_bytes(), true) {
            return Err(self.refuse(ctx, "mknod", path, refusal));
        }
        let kind = match mode & libc::S_IFMT {
            libc::S_IFCHR => Some(DevKind::Char),
            libc::S_IFBLK => Some(DevKind::Block),
            _ => None,
        };
        let result = match kind {
            // A device node the host cannot make: an empty regular file
            // stands for it, the override saying what it is.
            Some(kind) if self.ownership => {
                let plain = (mode & !libc::S_IFMT) | libc::S_IFREG;
                let made = self.inner.mknod(&squash(ctx), inode, name, plain, 0, umask);
                match made {
                    Ok(entry) => {
                        let over = Override {
                            dev: Some((kind, u64::from(rdev))),
                            ..Override::default()
                        };
                        match self.write_override(ctx, entry.inode, &over) {
                            Ok(()) => Ok(entry),
                            Err(error) => {
                                // Not a device after all: the stand-in goes.
                                let _ = self.inner.unlink(&squash(ctx), inode, name);
                                self.inner.forget(&squash(ctx), entry.inode, 1);
                                Err(error)
                            }
                        }
                    }
                    Err(error) => Err(error),
                }
            }
            _ => self
                .inner
                .mknod(&squash(ctx), inode, name, mode, rdev, umask),
        };
        if let Ok(entry) = &result {
            self.remember(inode, name.to_bytes(), entry);
        }
        let result = self.present_entry(ctx, result);
        let payload = Payload::FsMknod(FsMknod {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            mode: effective_mode(mode, umask),
            rdev,
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn mkdir(
        &self,
        ctx: &Context,
        parent: u64,
        name: &CStr,
        mode: u32,
        umask: u32,
    ) -> io::Result<Entry> {
        self.refuse_if_log_failed()?;
        let path = self.child(parent, name);
        if let Err(refusal) = self.check_name(&self.rules.load(), parent, name.to_bytes(), true) {
            return Err(self.refuse(ctx, "mkdir", path, refusal));
        }
        let result = self.inner.mkdir(&squash(ctx), parent, name, mode, umask);
        if let Ok(entry) = &result {
            self.remember(parent, name.to_bytes(), entry);
        }
        let result = self.present_entry(ctx, result);
        let payload = Payload::FsMkdir(FsMkdir {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            mode: effective_mode(mode, umask),
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn unlink(&self, ctx: &Context, parent: u64, name: &CStr) -> io::Result<()> {
        self.refuse_if_log_failed()?;
        let path = self.child(parent, name);
        let rules = self.rules.load();
        let plain = Existing {
            holding: false,
            programs: false,
        };
        let checked = self
            .check_name(&rules, parent, name.to_bytes(), true)
            .and_then(|()| self.check_existing(&rules, parent, name.to_bytes(), plain));
        if let Err(refusal) = checked {
            return Err(self.refuse(ctx, "unlink", path, refusal));
        }
        let result = self.inner.unlink(&squash(ctx), parent, name);
        if result.is_ok() {
            self.write_paths().mark_deleted(parent, name.to_bytes());
        }
        let payload = Payload::FsUnlink(FsPathOp {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn rmdir(&self, ctx: &Context, parent: u64, name: &CStr) -> io::Result<()> {
        self.refuse_if_log_failed()?;
        let path = self.child(parent, name);
        let rules = self.rules.load();
        let holding = Existing {
            holding: true,
            programs: false,
        };
        let checked = self
            .check_name(&rules, parent, name.to_bytes(), true)
            .and_then(|()| self.check_existing(&rules, parent, name.to_bytes(), holding));
        if let Err(refusal) = checked {
            return Err(self.refuse(ctx, "rmdir", path, refusal));
        }
        let result = self.inner.rmdir(&squash(ctx), parent, name);
        if result.is_ok() {
            self.write_paths().mark_deleted(parent, name.to_bytes());
        }
        let payload = Payload::FsRmdir(FsPathOp {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn rename(
        &self,
        ctx: &Context,
        olddir: u64,
        oldname: &CStr,
        newdir: u64,
        newname: &CStr,
        flags: u32,
    ) -> io::Result<()> {
        self.refuse_if_log_failed()?;
        let from = self.child(olddir, oldname);
        let to = self.child(newdir, newname);
        let rules = self.rules.load();
        let (old, new) = (oldname.to_bytes(), newname.to_bytes());
        // Both names change, and with RENAME_EXCHANGE each is moved: a
        // directory holding denied entries, a literal prefix and a refused
        // program move neither way.
        let both = Existing {
            holding: true,
            programs: true,
        };
        let checked = self
            .check_name(&rules, olddir, old, true)
            .and_then(|()| self.check_name(&rules, newdir, new, true))
            .and_then(|()| self.check_moved(&rules, olddir, old))
            .and_then(|()| self.check_moved(&rules, newdir, new))
            .and_then(|()| self.check_existing(&rules, olddir, old, both))
            .and_then(|()| self.check_existing(&rules, newdir, new, both));
        if let Err(refusal) = checked {
            return Err(self.refuse(ctx, "rename", from, refusal));
        }
        let result = self
            .inner
            .rename(&squash(ctx), olddir, oldname, newdir, newname, flags);
        if result.is_ok() {
            let (old, new) = (oldname.to_bytes(), newname.to_bytes());
            let mut paths = self.write_paths();
            if flags & libc::RENAME_EXCHANGE != 0 {
                paths.exchange(olddir, old, newdir, new);
            } else {
                paths.rename(olddir, old, newdir, new);
            }
        }
        let payload = Payload::FsRename(FsRename {
            mount: self.events.mount(),
            from: from.path,
            to: to.path,
            flags,
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn link(&self, ctx: &Context, inode: u64, newparent: u64, newname: &CStr) -> io::Result<Entry> {
        self.refuse_if_log_failed()?;
        let target_path = self.path(inode).path;
        let path = self.child(newparent, newname);
        let rules = self.rules.load();
        // The new name, and the inode itself: a link changes its link
        // count, so every name it has must be writable, and a refused
        // program gets no new name.
        let checked = self
            .check_name(&rules, newparent, newname.to_bytes(), true)
            .and_then(|()| self.check_inode(&rules, inode, true, true));
        if let Err(refusal) = checked {
            return Err(self.refuse(ctx, "link", path, refusal));
        }
        let result = self.inner.link(&squash(ctx), inode, newparent, newname);
        if let Ok(entry) = &result {
            self.remember(newparent, newname.to_bytes(), entry);
        }
        let result = self.present_entry(ctx, result);
        let payload = Payload::FsLink(FsLink {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            target_path,
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn open(
        &self,
        ctx: &Context,
        inode: u64,
        flags: u32,
        fuse_flags: u32,
    ) -> io::Result<(Option<u64>, OpenOptions, Option<u32>)> {
        let truncates = flags & libc::O_TRUNC as u32 != 0;
        let changes = opens_for_writing(flags) || truncates;
        if changes {
            self.refuse_if_log_failed()?;
        }
        let path = self.path(inode);
        // Any open of a refused program: to run it, or to read it for a
        // loader or a copy.
        if let Err(refusal) = self.check_inode(&self.rules.load(), inode, changes, true) {
            let op = if is_exec(flags) { "exec" } else { "open" };
            return Err(self.refuse(ctx, op, path, refusal));
        }
        let result = self.inner.open(&squash(ctx), inode, flags, fuse_flags);
        let fh = match &result {
            Ok((handle, _, _)) => handle.unwrap_or(0),
            Err(_) => 0,
        };
        if result.is_ok() && truncates {
            self.content_changed(inode);
        }
        if result.is_ok() {
            let entry = HandleEntry {
                ino: inode,
                path_at_open: path.path.clone(),
                flags,
                opener: subject(ctx),
                open_seq: None,
                bytes_read: 0,
                bytes_written: 0,
                wrote: false,
                created: false,
                truncated: truncates,
            };
            self.opened(fh, entry);
        }
        let payload = Payload::FsOpen(FsOpen {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            fh,
            flags,
            flags_decoded: decode_open_flags(flags),
            exec: is_exec(flags),
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn create(
        &self,
        ctx: &Context,
        parent: u64,
        name: &CStr,
        args: CreateIn,
    ) -> io::Result<(Entry, Option<u64>, OpenOptions, Option<u32>)> {
        self.refuse_if_log_failed()?;
        let path = self.child(parent, name);
        let rules = self.rules.load();
        // An existing file is opened, and may be truncated, before any reply
        // could be checked: what the name is now is read first.
        let opens = Existing {
            holding: false,
            programs: true,
        };
        let checked = self
            .check_name(&rules, parent, name.to_bytes(), true)
            .and_then(|()| self.check_existing(&rules, parent, name.to_bytes(), opens));
        if let Err(refusal) = checked {
            return Err(self.refuse(ctx, "create", path, refusal));
        }
        let result = self.inner.create(&squash(ctx), parent, name, args).map(
            |(mut entry, handle, opts, flags)| {
                self.present(ctx, entry.inode, &mut entry.attr);
                (entry, handle, opts, flags)
            },
        );
        if let Ok((entry, handle, _, _)) = &result {
            // Creating an existing file opens it: under another name it may
            // be one the scan found denied.
            if let Err(refusal) = self.check_reply(&rules, entry, false) {
                if let Some(handle) = handle {
                    let _ = self.inner.release(
                        &squash(ctx),
                        entry.inode,
                        args.flags,
                        *handle,
                        false,
                        false,
                        None,
                    );
                }
                self.inner.forget(&squash(ctx), entry.inode, 1);
                return Err(self.refuse(ctx, "create", path, refusal));
            }
        }
        let fh = match &result {
            Ok((_, handle, _, _)) => handle.unwrap_or(0),
            Err(_) => 0,
        };
        if let Ok((entry, _, _, _)) = &result {
            self.remember(parent, name.to_bytes(), entry);
            // Creating an existing file without O_EXCL opens it, and may
            // truncate it.
            self.content_changed(entry.inode);
            let handle = HandleEntry {
                ino: entry.inode,
                path_at_open: path.path.clone(),
                flags: args.flags,
                opener: subject(ctx),
                open_seq: None,
                bytes_read: 0,
                bytes_written: 0,
                wrote: false,
                created: true,
                truncated: args.flags & libc::O_TRUNC as u32 != 0,
            };
            self.opened(fh, handle);
        }
        let payload = Payload::FsCreate(FsCreate {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            fh,
            mode: effective_mode(args.mode, args.umask),
            flags: args.flags,
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn read(
        &self,
        ctx: &Context,
        inode: u64,
        handle: u64,
        w: &mut dyn ZeroCopyWriter,
        size: u32,
        offset: u64,
        lock_owner: Option<u64>,
        flags: u32,
    ) -> io::Result<usize> {
        let result = self.inner.read(
            &squash(ctx),
            inode,
            handle,
            w,
            size,
            offset,
            lock_owner,
            flags,
        );
        let done = result.as_ref().map_or(0, |&n| n as u64);
        let opener = self.handles.update(handle, |e| {
            e.bytes_read = e.bytes_read.saturating_add(done);
            e.opener
        });
        if self.verbose() {
            let len = match &result {
                Ok(n) => u32::try_from(*n).unwrap_or(u32::MAX),
                Err(_) => size,
            };
            let (who, attrib) = self.io_subject(ctx, opener, false);
            let path = self.path(inode);
            let payload = Payload::FsRead(FsIo {
                mount: self.events.mount(),
                path: path.path,
                path_b64: path.path_b64,
                fh: handle,
                offset,
                len,
                result: op_result(&result),
                attrib,
            });
            self.events.sample(Some(who), payload);
        }
        result
    }

    fn write(
        &self,
        ctx: &Context,
        inode: u64,
        handle: u64,
        r: &mut dyn ZeroCopyReader,
        size: u32,
        offset: u64,
        lock_owner: Option<u64>,
        delayed_write: bool,
        flags: u32,
        fuse_flags: u32,
    ) -> io::Result<usize> {
        self.refuse_if_log_failed()?;
        // Checked at every write, not only at the open: a handle opened
        // under a writable exception stops writing when it expires.
        if let Err(refusal) = self.check_inode(&self.rules.load(), inode, true, false) {
            return Err(self.refuse(ctx, "write", self.path(inode), refusal));
        }
        let result = self.inner.write(
            &squash(ctx),
            inode,
            handle,
            r,
            size,
            offset,
            lock_owner,
            delayed_write,
            flags,
            fuse_flags,
        );
        let done = result.as_ref().map_or(0, |&n| n as u64);
        if done > 0 {
            self.content_changed(inode);
        }
        let opener = self.handles.update(handle, |e| {
            e.bytes_written = e.bytes_written.saturating_add(done);
            e.wrote |= done > 0;
            e.opener
        });
        if self.verbose() {
            let len = match &result {
                Ok(n) => u32::try_from(*n).unwrap_or(u32::MAX),
                Err(_) => size,
            };
            // A write-back from the guest's page cache is made by whichever
            // thread flushes it, not by the process that wrote the data.
            let cached = delayed_write || fuse_flags & WRITE_CACHE != 0;
            let (who, attrib) = self.io_subject(ctx, opener, cached);
            let path = self.path(inode);
            let payload = Payload::FsWrite(FsIo {
                mount: self.events.mount(),
                path: path.path,
                path_b64: path.path_b64,
                fh: handle,
                offset,
                len,
                result: op_result(&result),
                attrib,
            });
            self.events.sample(Some(who), payload);
        }
        result
    }

    fn fallocate(
        &self,
        ctx: &Context,
        inode: u64,
        handle: u64,
        mode: u32,
        offset: u64,
        length: u64,
    ) -> io::Result<()> {
        self.refuse_if_log_failed()?;
        let path = self.path(inode);
        if let Err(refusal) = self.check_inode(&self.rules.load(), inode, true, false) {
            return Err(self.refuse(ctx, "fallocate", path, refusal));
        }
        let result = self
            .inner
            .fallocate(&squash(ctx), inode, handle, mode, offset, length);
        if result.is_ok() {
            // Allocating past the end, punching a hole or zeroing a range
            // all change what the file reads as.
            self.content_changed(inode);
            self.handles.update(handle, |e| e.wrote = true);
        }
        let payload = Payload::FsFallocate(FsFallocate {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            offset,
            len: length,
            mode,
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn release(
        &self,
        ctx: &Context,
        inode: u64,
        flags: u32,
        handle: u64,
        flush: bool,
        flock_release: bool,
        lock_owner: Option<u64>,
    ) -> io::Result<()> {
        let result = self.inner.release(
            &squash(ctx),
            inode,
            flags,
            handle,
            flush,
            flock_release,
            lock_owner,
        );
        // The kernel ignores the reply to a release: the handle is gone
        // either way.
        if let Some(entry) = self.handles.take(handle) {
            self.close(ctx, handle, entry);
        }
        result
    }

    fn setxattr(
        &self,
        ctx: &Context,
        inode: u64,
        name: &CStr,
        value: &[u8],
        flags: u32,
    ) -> io::Result<()> {
        self.refuse_if_log_failed()?;
        let path = self.path(inode);
        if let Err(refusal) = self.check_inode(&self.rules.load(), inode, true, false) {
            return Err(self.refuse(ctx, "setxattr", path, refusal));
        }
        let result = if is_ownership_xattr(name) {
            Err(io::Error::from_raw_os_error(libc::EPERM))
        } else {
            self.inner.setxattr(&squash(ctx), inode, name, value, flags)
        };
        let payload = Payload::FsXattr(FsXattr {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            name: c_text(name),
            op: "set".to_owned(),
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn removexattr(&self, ctx: &Context, inode: u64, name: &CStr) -> io::Result<()> {
        self.refuse_if_log_failed()?;
        let path = self.path(inode);
        if let Err(refusal) = self.check_inode(&self.rules.load(), inode, true, false) {
            return Err(self.refuse(ctx, "removexattr", path, refusal));
        }
        let result = if is_ownership_xattr(name) {
            Err(io::Error::from_raw_os_error(libc::EPERM))
        } else {
            self.inner.removexattr(&squash(ctx), inode, name)
        };
        let payload = Payload::FsXattr(FsXattr {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            name: c_text(name),
            op: "remove".to_owned(),
            result: op_result(&result),
        });
        self.events.record(Some(subject(ctx)), payload);
        result
    }

    fn readdir(
        &self,
        ctx: &Context,
        inode: u64,
        handle: u64,
        size: u32,
        offset: u64,
        add_entry: &mut dyn FnMut(DirEntry) -> io::Result<usize>,
    ) -> io::Result<()> {
        let result = self
            .inner
            .readdir(&squash(ctx), inode, handle, size, offset, add_entry);
        if self.verbose() {
            self.listed(ctx, inode, &result);
        }
        result
    }

    fn readdirplus(
        &self,
        ctx: &Context,
        inode: u64,
        handle: u64,
        size: u32,
        offset: u64,
        add_entry: &mut dyn FnMut(DirEntry, Entry) -> io::Result<usize>,
    ) -> io::Result<()> {
        // The kernel counts a lookup for every entry that makes it into the
        // reply, except `.` and `..`, and forgets them later like any other.
        // An entry the path rules deny, by its path or its identity, goes in
        // with node id 0, a name without attributes, as `readdir` gives it:
        // the kernel never gets its inode, and its lookup goes back here.
        let rules = self.rules.load();
        let mut returned: Vec<(Box<[u8]>, Entry)> = Vec::new();
        let mut withheld: Vec<u64> = Vec::new();
        let result = self.inner.readdirplus(
            &squash(ctx),
            inode,
            handle,
            size,
            offset,
            &mut |dirent, entry| {
                let dot = is_dot(dirent.name);
                let hide = !dot
                    && entry.inode != 0
                    && (self.check_name(&rules, inode, dirent.name, false).is_err()
                        || self.check_reply(&rules, &entry, false).is_err());
                if hide {
                    let added = add_entry(dirent, bare_entry())?;
                    if added > 0 {
                        withheld.push(entry.inode);
                    }
                    return Ok(added);
                }
                let mut entry = entry;
                if !dot {
                    self.present(ctx, entry.inode, &mut entry.attr);
                }
                let added = add_entry(dirent, entry)?;
                // 0: the reply is full and the entry was not added.
                if added > 0 && !dot {
                    returned.push((dirent.name.into(), entry));
                }
                Ok(added)
            },
        );
        for withheld in withheld {
            self.inner.forget(&squash(ctx), withheld, 1);
        }
        // An error reply carries no entries.
        if result.is_ok() && !returned.is_empty() {
            let mut paths = self.write_paths();
            for (name, entry) in &returned {
                paths.insert(inode, name, entry.inode);
                paths.set_host_id(entry.inode, host_id(&entry.attr));
            }
        }
        if self.verbose() {
            self.listed(ctx, inode, &result);
        }
        result
    }

    fn access(&self, ctx: &Context, inode: u64, mask: u32) -> io::Result<()> {
        self.gate(ctx, "access", inode)?;
        let result = self.inner.access(&squash(ctx), inode, mask);
        if let Err(e) = &result {
            if errno(e) == libc::EACCES {
                self.denied(ctx, "access", self.path(inode), libc::EACCES);
            }
        }
        result
    }
}

impl<F: FileSystem<Inode = u64, Handle = u64>> AuditFs<F> {
    fn overrides(&self) -> std::sync::MutexGuard<'_, HashMap<u64, Option<Override>>> {
        self.overrides
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
    }

    /// The override `inode` carries, from the cache or the host file's
    /// xattr; `None` without one, or with the override off.
    fn override_of(&self, ctx: &Context, inode: u64) -> Option<Override> {
        if !self.ownership {
            return None;
        }
        if let Some(cached) = self.overrides().get(&inode) {
            return *cached;
        }
        let name = CString::new(OWNERSHIP_XATTR).expect("a plain name");
        let read = self
            .inner
            .getxattr(&squash(ctx), inode, &name, 4096)
            .ok()
            .and_then(|reply| match reply {
                GetxattrReply::Value(value) => Override::parse(&value),
                GetxattrReply::Count(_) => None,
            })
            .filter(|over| !over.is_empty());
        self.overrides().insert(inode, read);
        read
    }

    /// Writes `over` as `inode`'s xattr and remembers it.
    fn write_override(&self, ctx: &Context, inode: u64, over: &Override) -> io::Result<()> {
        let name = CString::new(OWNERSHIP_XATTR).expect("a plain name");
        self.inner
            .setxattr(&squash(ctx), inode, &name, &over.encode(), 0)?;
        self.overrides().insert(inode, Some(*over));
        Ok(())
    }

    /// `st` as the guest is to see it: the override where there is one,
    /// else the session's own identity (with the override on).
    fn present(&self, ctx: &Context, inode: u64, st: &mut stat64) {
        if !self.ownership {
            return;
        }
        match self.override_of(ctx, inode) {
            Some(over) => over.apply(st),
            None => {
                st.st_uid = self.owner.0;
                st.st_gid = self.owner.1;
            }
        }
    }

    /// An entry's attributes as the guest is to see them.
    fn present_entry(&self, ctx: &Context, result: io::Result<Entry>) -> io::Result<Entry> {
        result.map(|mut entry| {
            if entry.inode != 0 {
                self.present(ctx, entry.inode, &mut entry.attr);
            }
            entry
        })
    }

    /// `fs.readdir`, at the verbose level.
    fn listed(&self, ctx: &Context, inode: u64, result: &io::Result<()>) {
        let path = self.path(inode);
        let payload = Payload::FsReaddir(FsPathOp {
            mount: self.events.mount(),
            path: path.path,
            path_b64: path.path_b64,
            result: op_result(result),
        });
        self.events.sample(Some(subject(ctx)), payload);
    }
}

/// The most bytes the kernel lists for an inode's xattr names.
const XATTR_LIST_MAX: u32 = 65536;

/// The invoking user's real uid and gid: the default owner shown.
fn invoking_user() -> (u32, u32) {
    // SAFETY: getuid and getgid take no arguments, touch no memory and
    // cannot fail.
    unsafe { (libc::getuid(), libc::getgid()) }
}

/// Whether `name` is the ownership override's xattr, boxcar's own.
fn is_ownership_xattr(name: &CStr) -> bool {
    name.to_bytes() == OWNERSHIP_XATTR.as_bytes()
}

/// `names` (NUL-separated) without the ownership override's.
fn without_ownership(names: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(names.len());
    for name in names.split(|&b| b == 0) {
        if !name.is_empty() && name != OWNERSHIP_XATTR.as_bytes() {
            out.extend_from_slice(name);
            out.push(0);
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use std::fs::{self, File};
    use std::io::{Seek, SeekFrom, Write};
    use std::sync::{Condvar, Mutex};

    use boxcar_audit::{spawn, LogReader, WriterConfig};
    use boxcar_proto::SessionId;
    use fuse_backend_rs::api::filesystem::ROOT_ID;
    use fuse_backend_rs::passthrough::PassthroughFs;
    use tempfile::TempDir;

    use super::*;
    use crate::share::{passthrough_config, CachePolicyKind};

    static GATE: Mutex<bool> = Mutex::new(false);
    static GATE_OPENED: Condvar = Condvar::new();

    /// Waits until the gate opens, then hashes as in production.
    fn hash_after_the_gate(
        root: &[OwnedFd],
        rel_path: &CString,
        expected: Option<FileId>,
        max: u64,
    ) -> crate::hasher::HashOutcome {
        let mut open = GATE.lock().unwrap();
        while !*open {
            open = GATE_OPENED.wait(open).unwrap();
        }
        drop(open);
        hash_file(root, rel_path, expected, max)
    }

    fn payload(data: &[u8]) -> File {
        let mut file = tempfile::tempfile().unwrap();
        file.write_all(data).unwrap();
        file.seek(SeekFrom::Start(0)).unwrap();
        file
    }

    const GUEST: Context = Context {
        uid: 1000,
        gid: 1000,
        pid: 42,
    };

    /// The content the first close hashed is the content its handle left
    /// behind, or it is `raced`: a write through another handle after the
    /// close, before the queued hash runs, is not the closer's.
    #[test]
    fn a_write_after_the_close_before_the_hash_makes_it_raced() {
        let dir = TempDir::new().unwrap();
        let root = dir.path().join("share");
        fs::create_dir(&root).unwrap();
        let (sink, writer) =
            spawn(WriterConfig::new(dir.path().join("data"), SessionId::new())).unwrap();
        let share = FsShareConfig {
            tag: "workspace".into(),
            host_dir: root.clone(),
            guest_path: "/workspace".into(),
            cache: CachePolicyKind::Auto,
            lower: None,
        };
        let inner = PassthroughFs::<()>::new(passthrough_config(&share)).unwrap();
        inner.import().unwrap();
        let root_fd = OwnedFd::from(File::open(&root).unwrap());
        let fs = AuditFs::with_hash(
            inner,
            &share,
            root_fd,
            sink,
            AuditFsOptions::default(),
            hash_after_the_gate,
        );
        let rw = (libc::O_RDWR | libc::O_CREAT) as u32;
        let args = CreateIn {
            flags: rw,
            mode: libc::S_IFREG | 0o644,
            umask: 0o022,
            fuse_flags: 0,
        };
        let write = |ino, fh, data: &[u8]| {
            let size = data.len() as u32;
            fs.write(
                &GUEST,
                ino,
                fh,
                &mut payload(data),
                size,
                0,
                None,
                false,
                rw,
                0,
            )
            .unwrap()
        };

        let name = CString::new("f").unwrap();
        let (entry, first, _, _) = fs.create(&GUEST, ROOT_ID, &name, args).unwrap();
        let (ino, first) = (entry.inode, first.unwrap());
        write(ino, first, b"one");
        // The close's hash waits behind the gate.
        fs.release(&GUEST, ino, rw, first, false, false, None)
            .unwrap();
        let (second, _, _) = fs.open(&GUEST, ino, libc::O_RDWR as u32, 0).unwrap();
        let second = second.unwrap();
        write(ino, second, b"two!");
        *GATE.lock().unwrap() = true;
        GATE_OPENED.notify_all();
        fs.release(&GUEST, ino, rw, second, false, false, None)
            .unwrap();
        fs.flush_hashes();

        let session = writer.session_dir().to_owned();
        drop(fs);
        writer.close().unwrap();
        let closes: Vec<FsClose> = LogReader::open(&session)
            .unwrap()
            .records()
            .filter_map(|r| match Payload::from_record(&r.unwrap()) {
                Ok(Payload::FsClose(c)) => Some(c),
                _ => None,
            })
            .collect();
        let of = |fh| closes.iter().find(|c| c.fh == fh).expect("a close");
        let (first, second) = (of(first), of(second));
        assert_eq!(first.hash_status, HashStatus::Raced, "{first:?}");
        assert_eq!(first.blake3, None, "{first:?}");
        assert_eq!(second.hash_status, HashStatus::Ok, "{second:?}");
        assert_eq!(
            second.blake3,
            Some(boxcar_proto::Hash::from_blake3(blake3::hash(b"two!")))
        );
    }

    /// A hash function that panics, as a bug in one would.
    fn panicking_hash(
        _: &[OwnedFd],
        _: &CString,
        _: Option<FileId>,
        _: u64,
    ) -> crate::hasher::HashOutcome {
        panic!("the hash function failed");
    }

    /// A hash thread that panics on a job still records that job's close,
    /// as `error` with no hash. (One job for each of the two threads: with
    /// both gone, a third would be hashed on this thread, and panic here.)
    #[test]
    fn a_hash_job_that_panics_records_an_error_close() {
        let dir = TempDir::new().unwrap();
        let root = dir.path().join("share");
        fs::create_dir(&root).unwrap();
        let (sink, writer) =
            spawn(WriterConfig::new(dir.path().join("data"), SessionId::new())).unwrap();
        let share = FsShareConfig {
            tag: "workspace".into(),
            host_dir: root.clone(),
            guest_path: "/workspace".into(),
            cache: CachePolicyKind::Auto,
            lower: None,
        };
        let inner = PassthroughFs::<()>::new(passthrough_config(&share)).unwrap();
        inner.import().unwrap();
        let root_fd = OwnedFd::from(File::open(&root).unwrap());
        let fs = AuditFs::with_hash(
            inner,
            &share,
            root_fd,
            sink,
            AuditFsOptions::default(),
            panicking_hash,
        );
        let rw = (libc::O_RDWR | libc::O_CREAT) as u32;
        let args = CreateIn {
            flags: rw,
            mode: libc::S_IFREG | 0o644,
            umask: 0o022,
            fuse_flags: 0,
        };
        // Quiet: the panics below are the test's.
        let hook = std::panic::take_hook();
        std::panic::set_hook(Box::new(|_| {}));
        let mut handles = Vec::new();
        for n in 0..2 {
            let name = CString::new(format!("f{n}")).unwrap();
            let (entry, fh, _, _) = fs.create(&GUEST, ROOT_ID, &name, args).unwrap();
            let fh = fh.unwrap();
            let size = 3;
            fs.write(
                &GUEST,
                entry.inode,
                fh,
                &mut payload(b"abc"),
                size,
                0,
                None,
                false,
                rw,
                0,
            )
            .unwrap();
            fs.release(&GUEST, entry.inode, rw, fh, false, false, None)
                .unwrap();
            handles.push(fh);
        }
        fs.flush_hashes();
        std::panic::set_hook(hook);

        let session = writer.session_dir().to_owned();
        drop(fs);
        writer.close().unwrap();
        let closes: Vec<FsClose> = LogReader::open(&session)
            .unwrap()
            .records()
            .filter_map(|r| match Payload::from_record(&r.unwrap()) {
                Ok(Payload::FsClose(c)) => Some(c),
                _ => None,
            })
            .collect();
        let mut recorded: Vec<u64> = closes.iter().map(|c| c.fh).collect();
        recorded.sort_unstable();
        handles.sort_unstable();
        assert_eq!(recorded, handles, "every close is recorded");
        for close in &closes {
            assert_eq!(close.hash_status, HashStatus::Error, "{close:?}");
            assert_eq!((close.size, close.blake3), (None, None));
            assert_eq!(close.bytes_written, 3);
            assert!(close.ts_release_ns > 0);
        }
    }

    fn zero_stat() -> stat64 {
        // SAFETY: stat64 is plain data; all-zero is a valid value.
        unsafe { std::mem::zeroed() }
    }

    #[test]
    fn only_the_valid_fields_are_recorded() {
        let mut attr = zero_stat();
        attr.st_mode = libc::S_IFREG | 0o4755;
        attr.st_uid = 7;
        attr.st_gid = 8;
        attr.st_size = 99;
        attr.st_atime = 1000;
        attr.st_mtime = 2000;
        let all = SetattrValid::MODE
            | SetattrValid::UID
            | SetattrValid::GID
            | SetattrValid::SIZE
            | SetattrValid::ATIME
            | SetattrValid::MTIME;
        assert_eq!(
            set_attrs(&attr, all, None),
            SetAttr {
                mode: Some(0o4755),
                uid: Some(7),
                gid: Some(8),
                size: Some(99),
                atime: Some(1000),
                mtime: Some(2000),
            }
        );
        assert_eq!(
            set_attrs(&attr, SetattrValid::empty(), None),
            SetAttr::default()
        );
    }

    #[test]
    fn now_times_come_from_the_reply() {
        let attr = zero_stat();
        let mut reply = zero_stat();
        reply.st_mtime = 1_800_000_000;
        let valid = SetattrValid::MTIME | SetattrValid::MTIME_NOW;
        assert_eq!(
            set_attrs(&attr, valid, Some(&reply)).mtime,
            Some(1_800_000_000)
        );
        let clock = set_attrs(&attr, valid, None).mtime.unwrap();
        assert!(clock > 1_700_000_000, "falls back to the clock: {clock}");
    }

    #[test]
    fn modes_are_masked_by_the_umask() {
        assert_eq!(effective_mode(0o777, 0o022), 0o755);
        assert_eq!(
            effective_mode(libc::S_IFIFO | 0o666, 0o027),
            libc::S_IFIFO | 0o640
        );
        assert_eq!(
            effective_mode(0o644, 0o7000),
            0o644,
            "only permission bits mask"
        );
    }

    #[test]
    fn the_masked_options_are_writeback_and_dax() {
        assert!(MASKED_OPTIONS.contains(FsOptions::WRITEBACK_CACHE));
        assert!(MASKED_OPTIONS.contains(FsOptions::MAP_ALIGNMENT));
        assert!(MASKED_OPTIONS.contains(FsOptions::PERFILE_DAX));
        assert!(!MASKED_OPTIONS.contains(FsOptions::DO_READDIRPLUS));
    }
}
